	/**
	 * Cuenta cuántas etiquetas {{PREFIJO_n}} (p.ej. {{FIRMANTE_1}}, {{FIRMANTE_2}}) aparecen en el
	 * contenido de la plantilla para un prefijo dado. UARIV-202605 CA-1.1.4: la plantilla asociada al
	 * flujo de aprobación debe contener tantas etiquetas por etapa como participantes se asignen.
	 */
	public function countEtiquetasPorPrefijo($prefijo){
		if(empty(trim((string)$prefijo)) || trim($this->getContents()) === ''){
			return 0;
		}
		//*****************************************************************************************************
		$patron = '/\{\{\s*'.preg_quote(strtoupper(trim($prefijo)),'/').'_\d+\s*\}\}/i';
		$cantidad = preg_match_all($patron,(string)$this->getContents(),$coincidencias);
		//*****************************************************************************************************
		return $cantidad === false ? 0 : $cantidad;
	}

	/**
	 * Carpeta (fuera de web/) donde se guardan los Word base de las plantillas.
	 */
	public static function getDocxStorageDir(){
		$dir_raiz = simad_util::NormalizePath(ParametroPeer::retrieveByPk(75)->getValortexto() . 'uploads');
		return simad_util::createPath($dir_raiz . DIRECTORY_SEPARATOR . 'plantillas');
	}

	/**
	 * Ruta real del Word base si existe y esta dentro de la carpeta de almacenamiento; null en otro caso.
	 */
	public function getDocxBasePath(){
		$url = trim((string)$this->getUrlDocx());
		if($url === ''){
			return null;
		}
		$real = realpath($url);
		$raiz = realpath(self::getDocxStorageDir());
		if($real === false || $raiz === false || strpos($real, $raiz . DIRECTORY_SEPARATOR) !== 0 || !is_file($real)){
			return null;
		}
		return $real;
	}

	/**
	 * Etiquetas {[X]} del Word que no existen como variable del modulo de la plantilla.
	 * @throws RuntimeException si el archivo no es un Word legible
	 */
	public function getEtiquetasDesconocidasDocx($docxPath){
		$desconocidas = PlantillaVariables::getDesconocidas(simad_util::extractPlaceholdersFromDocx($docxPath), $this->getModuloId());
		// Las etiquetas que el administrador confirmo al cargar el Word base de la plantilla no cuentan como error
		if(count($desconocidas) > 0 && $this->hasDocxBase()){
			$aprobadas = PlantillaVariables::getDesconocidas(simad_util::extractPlaceholdersFromDocx($this->getDocxBasePath()), $this->getModuloId());
			$desconocidas = array_values(array_diff($desconocidas, $aprobadas));
		}
		return $desconocidas;
	}

	/**
	 * Modulos cuyas plantillas pueden trabajar con un documento Word en lugar del editor de texto.
	 */
	public static function admiteWord($modulo_id){
		return in_array((int)$modulo_id, array(ModulesEnable::ComInterna, ModulesEnable::ComEnviada, ModulesEnable::ActosAdministrativos), true);
	}

	/**
	 * Carpeta temporal (misma raiz, fuera de web/) donde queda el Word cargado hasta que se guarda la plantilla.
	 */
	public static function getDocxTempDir(){
		return simad_util::createPath(self::getDocxStorageDir() . DIRECTORY_SEPARATOR . 'tmp');
	}

	/**
	 * Ruta del Word temporal identificado por $token (nombre generado al cargarlo); null si no es valido o no existe.
	 */
	public static function getDocxTempPath($token){
		$token = trim((string)$token);
		if(!preg_match('/^[a-f0-9]{32}\.docx$/', $token)){
			return null;
		}
		$path = self::getDocxTempDir() . DIRECTORY_SEPARATOR . $token;
		return is_file($path) ? $path : null;
	}

	/**
	 * El Word base solo se usa cuando la plantilla tiene deshabilitado el editor de texto.
	 */
	public function hasDocxBase(){
		return !$this->getUsaEditor() && $this->getDocxBasePath() !== null;
	}

	/**
	 * Propiedades que identifican al Word generado con esta plantilla; se validan al volver a cargarlo.
	 */
	private function buildWordCustomProps($metadatos){
		//version original, permite cualquier documento sin importar que sea de la comunicacion
		$uuid = $this->getPrimaryKey().'#'.$this->getModuloId();
		$plantillaId = $this->getPrimaryKey();
		$borradorId = $metadatos['comobject_id'];
		$hmac = $this->makeHmac($uuid, $plantillaId, $metadatos['periodo_id'], $this->getModuloId());
		return array(
			'xd_uuid' => hash('sha256', (string)$uuid),
			'xd_hmac' => $hmac,
			'xd_borrador_id' => hash('sha256', (string)$borradorId),
			'xd_plantilla_id' => hash('sha256', (string)$plantillaId),
		);
	}

	private function buildWordFilename($metadatos){
		$borradorId = $metadatos['comobject_id'];
		if($this->getModuloId() == ModulesEnable::ComEnviada){
			$tipo = 'ComEnviada';
		}elseif($this->getModuloId() == ModulesEnable::ActosAdministrativos){
			$tipo = 'ActoAdmin';
		}elseif($this->getModuloId() == ModulesEnable::ComInterna){
			$tipo = 'ComInterna';
		}else{
			$tipo = 'Generica';
		}
		return 'doc_'.uniqid()."_{$tipo}_{$borradorId}_".$metadatos['periodo_id'].'.docx';
	}

	/**
	 * Copia el Word base tal cual (membrete, estilos, tablas, encabezados y pies) y le agrega las
	 * propiedades de identificacion, para que el usuario lo descargue, edite y vuelva a cargar.
	 */
	private function generateWordFromDocxBase($savePath, $metadatos){
		$fullpath = $savePath.DIRECTORY_SEPARATOR.$this->buildWordFilename($metadatos);
		if(!copy($this->getDocxBasePath(), $fullpath)){
			return array('isError' => true, 'message' => 'No se pudo copiar el documento Word de la plantilla');
		}
		simad_util::setCustomPropsInDocx($fullpath, $this->buildWordCustomProps($metadatos));
		return array('isError' => false, 'message' => 'Plantilla generada exitosamente', 'path_plantilla' => $fullpath);
	}

	public function generateWordByPlantilla($savePath, $metadatos = array()){
		try {
			if($this->hasDocxBase()){
				return $this->generateWordFromDocxBase($savePath, $metadatos);
			}
			//*********************************************************************************
			$phpWord = new \PhpOffice\PhpWord\PhpWord();
			//*********************************************************************************
			// Adding Text element to the Section having font styled by default...
			$section = $phpWord->addSection([
				'pageSizeW'   => 11906, // A4 8.27in * 1440 twips/in
				'pageSizeH'   => 16838, // A4 11.69in * 1440
				'marginLeft'  => 1440,  // 1 in
				'marginRight' => 1440,
				'marginTop'   => 1440,
				'marginBottom'=> 1440,
			]);
			//*********************************************************************************
			$url_mebrete = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR.'images'.DIRECTORY_SEPARATOR.'encabezado_carta';
			$membrete_com = isset($metadatos['membrete_com']) ?  $metadatos['membrete_com'] : $url_mebrete.DIRECTORY_SEPARATOR.$this->getImageMembrete();
			//*********************************************************************************
			if($this->getUseMembrete()){
				$use_membrete_com = $this->getUseMembrete();
				$path_membrete = $url_mebrete.DIRECTORY_SEPARATOR.$this->getImageMembrete();
				
				if(empty(trim($this->getImageMembrete()))){
					$path_membrete = $url_mebrete.DIRECTORY_SEPARATOR.$membrete_com;
				}
			}elseif(isset($metadatos['use_membrete'])){
				$use_membrete_com = $metadatos['use_membrete'];
				$membrete_com = isset($metadatos['membrete_com']) ?  $metadatos['membrete_com'] : $url_mebrete.DIRECTORY_SEPARATOR.$this->getImageMembrete();
				$path_membrete = $url_mebrete.DIRECTORY_SEPARATOR.$membrete_com;
			}
			//*********************************************************************************
			if($use_membrete_com == true && file_exists($path_membrete)){
				$style = $section->getStyle();
				$pageWidthInch  = $style->getPageSizeW() / 1440.0;
				$pageHeightInch = $style->getPageSizeH() / 1440.0;
				$pageWidth2Px  = Converter::inchToPixel($pageWidthInch);
				$pageHeightPx = Converter::inchToPixel($pageHeightInch);
				$pageWidthNewPx  = (int) round($pageWidth2Px  * 0.75);
    			$pageHeightNewPx = (int) round($pageHeightPx * 0.75);
				//*****************************************************************************
				$header = $section->addHeader();
				$header->addImage($path_membrete,
					[
						'width' 		   => $pageWidthNewPx,
						'height' 		   => $pageHeightNewPx,
						'positioning' 	   => 'absolute',
						'posHorizontal'    => 'center',
						'posHorizontalRel' => 'page',
						'posVertical' 	   => 'top',
						'posVerticalRel'   => 'page',
						'wrappingStyle'    => 'behind'
					]
				);
			}
			//*********************************************************************************
			$htmlLimpio = simad_util::sanitizeForPhpWord($this->getContents());
			Html::addHtml($section, $htmlLimpio, false, false);
			//*********************************************************************************
			$custom_props = $this->buildWordCustomProps($metadatos);
			//*********************************************************************************
			// Adding Text element with font customized inline...
			$docInfo = $phpWord->getDocInfo();
			$docInfo->setCompany('SGDEA');
			$docInfo->setTitle($this->getNombre());
			$docInfo->setCategory('SGDEA modulo correspondencia');
			$docInfo->setCreated(time());
			//*********************************************************************************
			//add custom properties
			foreach($custom_props as $prop_name => $prop_value){
				$docInfo->setCustomProperty($prop_name, $prop_value);
			}
			//*********************************************************************************
			$fullpath = $savePath.DIRECTORY_SEPARATOR.$this->buildWordFilename($metadatos);
			IOFactory::createWriter($phpWord, 'Word2007')->save($fullpath);
			//*********************************************************************************
			if(file_exists($fullpath)){
				return array('isError' => false, 'message' => 'Plantilla generada exitosamente', 'path_plantilla' => $fullpath);
			}else{
				return array('isError' => true, 'message' => 'Ocurrio un error al crear la plantilla, intente de nuevo o comuniquese con el administrador');
			}

		} catch (PropelException $th) {
			return array('isError' => true, 'message' => $th->getMessage());
		} catch (\Exception $th) {
			return array('isError' => true, 'message' => $th->getMessage());
		} catch (\Throwable $th) {
			return array('isError' => true, 'message' => $th->getMessage());
		}
	}

	/** Crea token HMAC para el borrador */
    public function makeHmac(string $uuid, int $plantillaId, string $periodoAt, int $moduloId): string
    {
		$key_config = simad_util::readConfigFileApp(array('keyprivate_svc_password'));
		$payload = $uuid . '|' . $plantillaId . '|' . $periodoAt. '|' . $moduloId;
        return hash_hmac('sha256', $payload, $key_config['keyprivate_svc_password']);
    }
